using System.Reflection;using NUnit.Framework;using Rootborn.UI.Modern;using Rootborn.UI.Objectives;using UnityEngine;
namespace Rootborn.Tests.EditMode.UI {public sealed class UrbanHudHostLayoutTests {
 [Test] public void Installer_ReinstallDoesNotShrinkTrackedHostOrCoverRightEdgeControls(){var go=new GameObject("host",typeof(RectTransform));try{var method=typeof(ModernUiPanelAutoInstaller).GetMethod("EnsurePanelHost",BindingFlags.Static|BindingFlags.NonPublic).MakeGenericMethod(typeof(TrackedObjectiveHud));var h=(TrackedObjectiveHud)method.Invoke(null,new object[]{go.transform,"TrackedObjectiveHud"});var rt=(RectTransform)h.transform;typeof(ModernUiPanelAutoInstaller).GetMethod("PositionTrackedObjectiveHud",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{rt});Assert.That(rt.sizeDelta.x,Is.GreaterThanOrEqualTo(640));Assert.That(rt.sizeDelta.y,Is.GreaterThanOrEqualTo(200));Assert.That(rt.anchoredPosition.x,Is.LessThanOrEqualTo(-204));Assert.That(method.Invoke(null,new object[]{go.transform,"TrackedObjectiveHud"}),Is.SameAs(h));Assert.That(rt.sizeDelta.y,Is.GreaterThanOrEqualTo(200));}finally{Object.DestroyImmediate(go);}}
}}
